/* Flip cards for 2026-27 grades 3-5.

   level tells you where a card came from and how hard it should feel:
     jacket   - restates the published summary. Easiest, and a battle would
                rarely use it, because the clue is close to the blurb.
     local    - a central plot fact most readers will remember.
     regional - a smaller but solid detail.
     state    - the kind of trivia that separates strong teams.

   No page numbers. Page numbers move between printings, and these were not
   checked against the official ISBNs. Confirm anything you plan to use in a
   real battle against the book itself. */

let counter = 0;

function q(bookId, type, pattern, level, prompt, answer, alternates, parts) {
  counter += 1;
  return {
    id: bookId + "-" + String(counter).padStart(3, "0"),
    bookId,
    type,
    pattern,
    level,
    prompt,
    answer: answer || null,
    alternates: alternates || [],
    parts: parts || null
  };
}

